def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix, k=3, alpha=0.5):
    if not unvisited_nodes:
        return destination_node
    weighted_scores = {}
    for node in unvisited_nodes:
        local_dist = distance_matrix[current_node][node]
        global_dist = distance_matrix[node][destination_node]
        weighted_scores[node] = alpha * local_dist + (1 - alpha) * global_dist
    top_k_nodes = sorted(unvisited_nodes, key=lambda node: weighted_scores[node])[:k]
